62. fn book_physical_memory_regions(
63.     physical_memory_regions: LinkedList<TruncatedMemoryRegion<PhysicalAddress>>,
64. ) -> Result<(), Error> {
65.     info!("booking physical memory regions ...");
66. 
67.     // Book physical memory that is not usable.
68.     for region in physical_memory_regions.iter() {
69.         info!("booking: {:?}", region);
70.         frame::alloc_range(region)?;
71.     }
72. 
73.     Ok(())
74. }
75. 
76. fn book_mmio_regions(
77.     mmio_regions: &LinkedList<TruncatedMemoryRegion<VirtualAddress>>,
78. ) -> Result<(), Error> {
79.     info!("booking memory-mapped i/o regions ...");
80. 
81.     // Book memory-mapped I/O regions.
82.     for region in mmio_regions.iter() {
83.         info!("booking: {:?}", region);
84.         let mut start: usize = region.start().into_raw_value();
85.         let end: usize = start + (region.size() - 1);
86.         while start < end {
87.             let mmio_addr: VirtualAddress = VirtualAddress::from_raw_value(start);
88.             let phys_addr: PageAligned<PhysicalAddress> = PageAligned::from_address(unsafe {
89.                 PhysicalAddress::from_mmio_address(mmio_addr)?
90.             })?;
91. 
92.             // Attempt to book underlying frame.
93.             match frame::book(phys_addr) {
94.                 // Frame successfully booked.
95.                 Ok(()) => {},
96.                 // Frame lies outside addressable physical memory.
97.                 Err(e) if e.code == ErrorCode::InvalidArgument => {},
98.                 // Something went wrong.
99.                 Err(e) => {
100.                     warn!("failed to book frame for mmio region {:?} ({:?})", region, e);
101.                     return Err(e);
102.                 },
103.             }
104.             start += mem::FRAME_SIZE;
105.         }
106.     }
107. 
108.     Ok(())
109. }
110. 
111. ///
112. /// # Description
113. ///
114. /// Initializes the physical memory manager.
115. ///
116. /// # Parameters
117. ///
118. /// - `kpool_base`: Base address of the kernel page pool.
119. /// - `physical_memory_regions`: Physical memory regions to book.
120. /// - `mmio_regions`: Memory-mapped I/O regions to book.
121. /// - `physical_memory_layout`: Physical memory layout bitmap.
122. /// - `kpool_bitmap`: Bitmap for the kernel page pool.
123. ///
124. /// # Returns
125. ///
126. /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
127. ///
128. pub fn init(
129.     kpool_base: PageAligned<PhysicalAddress>,
130.     physical_memory_regions: LinkedList<TruncatedMemoryRegion<PhysicalAddress>>,
131.     mmio_regions: &LinkedList<TruncatedMemoryRegion<VirtualAddress>>,
132.     physical_memory_layout: SparseBitmap,
133.     kpool_bitmap: Bitmap,
134. ) -> Result<(), Error> {
135.     // Initialize frame allocator singleton.
136.     info!("initializing the frame allocator ...");
137.     // Safety: called exactly once during single-threaded boot.
138.     unsafe { frame::init(physical_memory_layout)? };
139.     book_physical_memory_regions(physical_memory_regions)?;
140. 
141.     book_mmio_regions(mmio_regions)?;
142. 
143.     // Initialize kernel page pool singleton.
144.     info!("initializing the kernel page pool ...");
145.     // Safety: called exactly once during single-threaded boot.
146.     let kpool: Kpool = unsafe { kpool::init(kpool_base, kpool_bitmap)? };
147. 
148.     // Initialize user page pool.
149.     info!("initializing the user page pool ...");
150.     let upool: Upool = Upool::new();
151. 
152.     // Initialize physical memory manager singleton.
153.     info!("initializing the physical memory manager ...");
154.     PhysMemoryManager::init(kpool, upool)?;
155. 
156.     Ok(())
157. }
